def is_power_of_5(N):
    if N <= 0:
        return False
    if N == 1: # 5^0 = 1, but we expect k >= 1 since 2^3 - 3 = 5.
        # Since the problem asks for 2^n - 3 = 5^k, and n >= 3, 2^n - 3 >= 5. So N >= 5.
        return False 

    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

print("Solutions found for n in [3, 20]:")
solutions = []
for n in range(3, 21):
    X = 2**n - 3
    if is_power_of_5(X):
        print(f"n={n}: 2^{n} - 3 = {X} = 5^k (Solution found)")
        solutions.append(n)

print("\nList of solutions:", solutions)

def is_power_of_two(x):
    return x > 0 and (x & (x - 1) == 0)

def check_k(k):
    target = 5**k + 3
    if is_power_of_two(target):
        print(f"k={k}: Target = {target}. Yes, it is a power of 2.")
    else:
        print(f"k={k}: Target = {target}. No, it is not a power of 2.")

check_k(1)
check_k(2)
check_k(3)
check_k(4)

def solve():
    for n in range(3, 100):
        val = 2**n - 3
        if val > 0:
            # Check if val is a power of 5
            k = 0
            temp = val
            while temp > 1 and temp % 5 == 0:
                temp //= 5
                k += 1
            if temp == 1:
                print(f"n={n}, val={val}, k={k}")

solve()

